'use client'

import { useEffect, useState } from 'react'
import { Wallet } from '@/types/wallet'
import {
  fetchUserWallets,
  createWallet,
} from '@/lib/walletApi'
import { getLoggedInUser } from '@/lib/auth' // localStorage-based user helper
import toast from 'react-hot-toast'

export default function WalletPage() {
  const [wallets, setWallets] = useState<Wallet[]>([])
  const [loading, setLoading] = useState(true)
  const [userId, setUserId] = useState<string | null>(null)

  useEffect(() => {
    const user = getLoggedInUser()
    if (!user) return toast.error('User not found')
    setUserId(user.id)
    loadWallets(user.id)
  }, [])

  async function loadWallets(uid: string) {
    setLoading(true)
    const data = await fetchUserWallets(uid)
    setWallets(data)
    setLoading(false)
  }

  async function handleCreateWallet() {
    if (!userId) return
    try {
      await createWallet(userId, 'USD', 0)
      toast.success('Wallet created successfully')
      await loadWallets(userId)
    } catch (err) {
      toast.error('Failed to create wallet')
    }
  }

  return (
    <div className="p-6 text-white">
      <h1 className="text-2xl font-bold mb-4">Your Wallet</h1>

      {loading ? (
        <p className="text-gray-400">Loading...</p>
      ) : wallets.length === 0 ? (
        <div className="bg-gray-800 p-4 rounded border border-gray-700">
          <p className="mb-2 text-gray-300">No wallet found.</p>
          <button
            onClick={handleCreateWallet}
            className="bg-blue-600 px-4 py-2 rounded hover:bg-blue-500"
          >
            Create Wallet
          </button>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {wallets.map((wallet) => (
            <div key={wallet.id} className="bg-gray-800 p-4 rounded border border-gray-700">
              <h2 className="text-lg font-semibold">{wallet.token}</h2>
              <p className="text-gray-400 mt-1">Balance: {wallet.balance.toFixed(6)}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
